def cross_product(o, a, b, px, py):
    """Compute cross product of vectors OA and OB, where O, A, B have coordinates at indices px, py"""
    return (a[px] - o[px]) * (b[py] - o[py]) - (a[py] - o[py]) * (b[px] - o[px])

def segments_intersect(p1, p2, p3, p4, coords_idx):
    """Check if two line segments (p1,p2) and (p3,p4) properly intersect"""
    cp1 = cross_product(p1, p2, p3, *coords_idx)
    cp2 = cross_product(p1, p2, p4, *coords_idx)
    cp3 = cross_product(p3, p4, p1, *coords_idx)
    cp4 = cross_product(p3, p4, p2, *coords_idx)

