        if i >= len(lines):
            break

        n = int(lines[i])

        # Find all divisors of n (greater than 1)
        divisors = []
        d = 2
        while d * d <= n:
            if n % d == 0:
                divisors.append(d)
                if d * d != n:
                    divisors.append(n // d)
            d += 1
        divisors.append(n)
        divisors.sort()

        # Count distinct prime factors of n
        temp = n
        distinct_primes = set()
        d = 2
        while d * d <= temp:
            if temp % d == 0:
                distinct_primes.add(d)
                while temp % d == 0:
                    temp //= d
            d += 1
        if temp > 1:
            distinct_primes.add(temp)

        distinct_count = len(distinct_primes)

        # Check if any two adjacent divisors (in original sorted order) are coprime
        coprime_adjacent = False
        m = len(divisors)
        for j in range(m):
            idx = j if j < m else 0
            if gcd(divisors[j], divisors[idx]) == 1:
                coprime_adjacent = True
                break

        # Generate the output
        if m <= 1:
            # Single divisor - any order is fine
            output_order = " ".join(map(str, divisors))
        else:
            # For valid arrangements with 0 moves, try to arrange optimally
            # Group divisors by their smallest prime factor
            if distinct_count >= 3:
                # Can arrange in a circle with no coprime adjacent pairs
                prime_divs = {}
                for d in divisors:
                    sp = get_smallest_prime(d)
                    if sp not in prime_divs:
                        prime_divs[sp] = []
                    prime_divs[sp].append(d)

                output_order = []
                keys = sorted(prime_divs.keys())
                last_added = -1

                for sp in keys:
                    div_list = prime_divs[sp][::-1]
                    for d in div_list:
                        output_order.append(d)
                        last_added = d

                # Check circular adjacency
