                    output_order.append(lcm(last_added, output_order[0]))
                    output_order = output_order[:-1]

                output_order = " ".join(map(str, output_order))
                if gcd(last_added, output_order[0]) == 1 and not output_order.endswith(" "):
                    output_order += " "
            else:
                # For 1 or 2 distinct primes, use a systematic approach
