    # For each variable i (1-indexed): x_i -> 2*(i-1), ~x_i -> 2*(i-1)+1
    graph = [[] for _ in range(2 * m)]

    def to_node(l):
        idx = abs(l) - 1
        return (idx << 1) if l > 0 else (idx << 1 | 1)

    def add_implication(u, v):
        graph[u].append(v)

