        if len(literals) == 1:
            # Clause (a) means a must be true: ~a -> a
            lit = to_node(literals[0])
            add_implication(lit ^ 1, lit)
        elif len(literals) == 2:
            # Clause (a OR b): ~a -> b AND ~b -> a
            a, b = to_node(literals[0]), to_node(literals[1])
            add_implication(a ^ 1, b)
            add_implication(b ^ 1, a)
        elif len(literals) >= 3:
            # Clause (a OR b OR c OR ...): pairwise implications
            # equivalent to: (a OR b) AND (a OR c) AND ...
            for i in range(len(literals)):
                for j in range(i + 1, len(literals)):
                    a, b = to_node(literals[i]), to_node(literals[j])
                    add_implication(a ^ 1, b)
                    add_implication(b ^ 1, a)

