def composition_matrix_exp(target, C, mod=1000000007):
    """Use matrix exponentiation to compute compositions"""
    max_c = max(C)
    if max_c > 100:
        max_c = 100

    M = [[0] * max_c for _ in range(max_c)]
    for i in range(max_c):
        for c in C:
            if i >= c and i - c >= 0:
                M[i - c][i] = 1

    # Power matrix
    def matmul(A, B, m):
        return [[sum(A[i][k]*B[k][j] for k in range(len(B))) % m for j in range(len(B[0]))] for i in range(len(A))]

    def matpow(A, p, m):
        res = [[int(i==j) for j in range(len(A))] for i in range(len(A))]
        B = A
        while p:
            if p & 1:
                res = matmul(res, B, m)
            B = matmul(B, B, m)
            p >>= 1
        return res

    if target <= 200:
        return compute_dp_direct(target, C, mod)

    # For large target, use matrix pattern
    res = matpow(M, target, mod)
    # Apply to initial vector [1, 0, 0, ...]
    return res[0][0] if target >= 0 else 0


