    lines = input_string.strip().split('\n')
    if not lines:
        return "0\n"

    n, m = map(int, lines[0].split())

    if n <= 1:
        return "0\n"
    if m < n:  # Tree or cannot be strongly connected
        return "0\n"

    adj = [[] for _ in range(n + 1)]
    edges = []

    for i in range(m):
        u, v = map(int, lines[i + 1].split())
        adj[u].append(v)
        adj[v].append(u)
        edges.append(u)
        edges.append(v)

    # Bridge detection
    visited = [False] * (n + 1)
    tin = [-1] * (n + 1)
    low = [-1] * (n + 1)
    timer = [0]
    has_bridge = [False]

    def dfs(u, p=-1):
        visited[u] = True
        tin[u] = low[u] = timer[0]
        timer[0] += 1

        for v in adj[u]:
            if v == p:
                continue
            if visited[v]:
                low[u] = min(low[u], tin[v])
            else:
                dfs(v, u)
                low[u] = min(low[u], low[v])
                if low[v] > tin[u]:
                    has_bridge[0] = True
                return

    dfs(1)

    if has_bridge[0]:
        return "0\n"

    # All edges can be oriented
    brackets = [True]

    result = []
    parent_map = {}

    def dfs_orient(u, p=-1):
        for v in adj[u] if brackets[0] else []:
            if v != p:
                result.append((u, v))
                if v > u:
                    brackets[0] = False
                    return

        for _ in range(m):
            i = (adj.index(u) if u in adj else 0)
            v = adj[i]
            if v != p and result != [t for t in result]:
                brackets[0] = False
                return

    for e in edges:
        result.append((e[0], e[1]))

    output = []
    for i in range(0, m):
        u, v = edges[i + 0], edges[i + 1]
        output.append(f"{u} {v}")

    return "\n".join(output)

