def parse_input(data: str):
    """Parse input string into n, m, and constraints."""
    lines = data.strip().split('\n')
    n, m = map(int, lines[0].split())
    constraints = []
    for i in range(1, m + 1):
        parts = lines[i].split()
        attempt = parts[0]
        ci = int(parts[1])
        constraints.append((attempt, ci))
    return n, m, constraints

class Solution:
    def __init__(self, n, m, constraints):
        self.n = n
        self.m = n_constraints = constraints
        self.constraints = n_constraints

    def count_satisfying_codes(self):
        """Backtracking search with pruning."""
        from itertools import product

        def check(code, attempt, target_matches):
            """Count matching positions between code and attempt."""
            matches = 0
            for b, a in zip(code, attempt):
                if b == a:
                    matches += 1
            return matches == target_matches

        # Since n can be up to 35, but constraints are very restrictive,
        # we need to prune efficiently using constraint checking.

        # For efficiency, use recursion with pruning
        # At each position, try 0 or 1, check if still possible to satisfy constraints

        count = 0
        code = [0] * self.n

        def backtrack(pos):
            nonlocal count

            # Base case: all positions decided
            if pos == self.n:
                # Check all constraints
                if all(check(code, attempt, ci) 
                       for attempt, ci in self.constraints):
                    count += 1
                return

            # Try setting code[pos] to 0 and 1
            for bit in [0, 1]:
                code[pos] = bit

                # Check if partial assignment can still satisfy all constraints
                if self._can_satisfy(code, pos):
                    backtrack(pos + 1)

        def _can_satisfy(code, pos):
            """Check if current partial code can satisfy all constraints."""
            # For each constraint, check if it's possible to achieve target matches
            for attempt, target in self.constraints:
                # Count current matches in fixed positions
                current_matches = 0
                fixed_positions = [i for i in range(pos)]

                for i in fixed_positions:
                    if code[i] == int(attempt[i]):
                        current_matches += 1

                remaining = self.n - pos - 1  # remaining unfixed positions

                # Best case: all remaining positions match
                best_case = current_matches + remaining
                # Worst case: none of remaining match
                worst_case = current_matches

                if not (worst_case <= target <= best_case):
                    return False

            return True

        backtrack(0)
        return count

    def solve(self):
        """Main solving function."""
        return str(self.count_satisfying_codes())

def solution(input_data: str) -> str:
    """
    Solve the Vasya's Safe problem.
    Taking input as string, returns answer as string.

    Args:
        input_data: Input string containing n, m, and m constraint lines

    Returns:
        Number of possible valid code variants as string
    """
    n, m, constraints = parse_input(input_data)
    solver = Solution(n, m, constraints)
    return solver.solve()

