def solution(input_string):
    """
    Solves the chessboard placement problem where we need to place pairs of chessmen
    at Manhattan distance exactly 3.

    Args:
        input_string: A string containing n and m separated by whitespace

    Returns:
        A string containing the maximum number of chessmen that can be placed
    """
    n, m = map(int, input_string.strip().split())

    # Ensure n <= m for consistent handling
    if n > m:
        n, m = m, n

    # For small boards where no valid pairs exist
    if n == 2 and m == 2:
        return "0"

    # For 1×m boards with m < 4, cannot form any distance-3 pairs
    if n == 1 and m < 4:
        return "0"

    # For 1×m boards with m >= 4, calculate maximum matching
    if n == 1:
        # For 1×m, cells at positions i and j where |i-j| = 3 can be paired
        # Calculate maximum independent sets in chains of distance-3 cells
        # Chain structure: cell i connects to cell i+3
        max_cells = 0
        # Process each chain starting from different residues
        for start in range(3):
            chain_len = m // 3 + (1 if (m % 3 > start) else 0)
            max_cells += 2 * (chain_len // 2)
        return str(max_cells)

    # For all other boards, we can achieve n*m cells if even, n*m-1 if odd
    total = n * m
    if total % 2 == 1:
        return str(total - 1)
    else:
        # Special check for 1×m case (n=1 already handled above)
        if n == 1:
            return str(min(total - 2, total))
        return str(total)


