def solution(input_str):
    s = input_str.rstrip('\n')
    n = len(s)
    MOD = 10**9 + 7
    pos = 0

    def power_of_10(length):
        result = 1
        base = 10
        while length > 0:
            if length & 1:
                result = (result * base) % MOD
            base = (base * base) % MOD
            length >>= 1
        return result

    def compute_range_value(l, r):
        result = 0
        for i in range(l, r + 1):
            s_i = str(i)
            len_i = len(s_i)
            multiplier = power_of_10(len_i)
            result = (result * multiplier + i) % MOD
        return result

    def get_total_length(l, r):
        total = 0
        for i in range(l, r + 1):
            total += len(str(i))
        return total

    def parse_number():
        nonlocal pos
        val = 0
        while pos < n and s[pos].isdigit():
            val = val * 10 + int(s[pos])
            pos += 1
        return val

    def parse_term():
        nonlocal pos
        # Check if this is a range (l-r) or just a number
        if pos < n and s[pos].isdigit():
            # Read the first number
            l_val = parse_number()
            # After reading, check if next is '-'
            if pos < n and s[pos] == '-':
                pos += 1
                r_val = parse_number()
                # Verify valid range
                if l_val <= r_val:
                    return compute_range_value(l_val, r_val), get_total_length(l_val, r_val)
            else:
                # Just a number
                return l_val, len(str(l_val))
        elif pos < n and s[pos] == '(':
            pos += 1  # consume '('
            val, length = parse_expression()
            if pos < n and s[pos] == ')':
                pos += 1  # consume ')'
            return val, length
        return 0, 0

    def parse_expression():
        nonlocal pos
        val, length = parse_term()
        while pos < n and s[pos] == '+':
            pos += 1
            term_val, term_len = parse_term()
            # Concatenate: val "..." + "..." term = val * 10^term_len + term
            total_len = length + term_len
            multiplier = power_of_10(term_len)
            val = (val * multiplier + term_val) % MOD
        return val, length

    val, _ = parse_expression()
    return str(val) + '\n'

