        dx, dy = directions[char]

        nx, ny = x + dx, y + dy
        while 0 <= nx < n and 0 <= ny < n:
            if work[nx][ny] == 1:
                return True
            nx += dx
            ny += dy
        return False

    # BFS to find all reachable cells from start
    work = [row[:] for row in grid]
    visited = [[False] * n for _ in range(n)]

    from collections import deque
    q = deque([(sx, sy)])
    visited[sx][sy] = True

    while q:
        cx, cy = q.popleft()

        for d_char in ['U', 'D', 'L', 'R']:
            dx, dy = {'U': (-1, 0), 'D': (1, 0), 'L': (0, -1), 'R': (0, 1)}[d_char]
            nx, ny = cx + dx, cy + dy

            if 0 <= nx < n and 0 <= ny < n and not visited[nx][ny]:
                if has_light_in_direction(work, cx, cy, d_char):
                    visited[nx][ny] = True
                    q.append((nx, ny))

    # Check if all lit cells are reachable
    unreachable_lights = 0
    initial_lights = []
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 1:
                initial_lights.append((i, j))
                if not visited[i][j]:
                    unreachable_lights += 1

    if unreachable_lights > 0:
        return "NO"

    # Construct the solution
    actions = []
    cx, cy = sx, sy

    # Direction mapping
    d_map = {'U': (-1, 0), 'D': (1, 0), 'L': (0, -1), 'R': (0, 1)}

    remaining = set(initial_lights)

    # If start has a light, turn it off
    if work[cx][cy] == 1:
        actions.append('2')
        work[cx][cy] = 0
        remaining.discard((cx, cy))

    # Visit all remaining lit cells
    while remaining:
        moved = False
        for tx, ty in list(remaining):
            if (tx, ty) == (cx, cy):
                continue

            for d_char in ['U', 'D', 'L', 'R']:
                dx, dy = d_map[d_char]
